import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadSantoshData(){const e=readFileSync(resolve(__dirname,"../../santosh-trophy-explorer/santosh-data.js"),"utf-8");return new Function(e+"\nreturn { SANTOSH_INFO, STATE_CHAMPIONS, NOTABLE_PLAYERS, TOURNAMENT_MILESTONES, REFERENCES };")()}describe("Santosh Trophy Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadSantoshData()}),describe("SANTOSH_INFO metadata",()=>{it("contains correct Santosh Trophy metadata and founding year 1941",()=>{expect(e.SANTOSH_INFO.id).toBe("santosh-trophy"),expect(e.SANTOSH_INFO.title).toContain("Santosh Trophy"),expect(e.SANTOSH_INFO.foundedYear).toBe("1941 CE"),expect(e.SANTOSH_INFO.namesake).toContain("Santosh")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.SANTOSH_INFO.quickStats)).toBe(!0),expect(e.SANTOSH_INFO.quickStats.length).toBe(6)})}),describe("STATE_CHAMPIONS & NOTABLE_PLAYERS",()=>{it("contains West Bengal 32 titles and legendary players",()=>{expect(Array.isArray(e.STATE_CHAMPIONS)).toBe(!0),expect(e.STATE_CHAMPIONS.length).toBeGreaterThanOrEqual(5);const t=e.STATE_CHAMPIONS.find(e=>"West Bengal"===e.state);expect(t).toBeDefined(),expect(t.titles).toBe(32),expect(Array.isArray(e.NOTABLE_PLAYERS)).toBe(!0);const a=e.NOTABLE_PLAYERS.find(e=>e.name.includes("Banerjee"));expect(a).toBeDefined()})}),describe("TOURNAMENT_MILESTONES & REFERENCES",()=>{it("contains historic milestones and reference citations",()=>{expect(Array.isArray(e.TOURNAMENT_MILESTONES)).toBe(!0),expect(e.TOURNAMENT_MILESTONES.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});